<?php
declare(strict_types=1);
if($argc<2){fwrite(STDERR,"Usage: php php/bootstrap.php PRIVATE_CONFIG.json [--once]\n");exit(2);}
$config=json_decode(file_get_contents($argv[1]),true,512,JSON_THROW_ON_ERROR);$directory=__DIR__.'/..';$file=$config['state_directory'].'/state.json';
if(is_file($file)){$saved=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);$update=$saved['update']??[];if(isset($update['current_code'])){$directory=($config['install_directory']??$config['state_directory'].'/runtime').'/'.$update['current_code'];$installed=json_decode(file_get_contents($directory.'/.installed.json'),true,512,JSON_THROW_ON_ERROR);if($installed['sha256']!==$update['sha256']||$installed['version_code']!==$update['current_code'])throw new RuntimeException('installed_version_pointer_invalid');}}
require $directory.'/php/worker.php';require $directory.'/php/updater.php';
try{$worker=new FleetWorker($config);$worker->store->lock();$updater=new FleetUpdater($config,$worker->store,$directory);do{try{$busy=$worker->tick();if(time()>=($worker->store->data['update_check_at']??0)+($config['update_poll_seconds']??900)){$worker->store->data['update_check_at']=time();$worker->store->save();$update=$updater->check();if($update['state']==='installed')exit(75);}}catch(FleetPending $e){fwrite(STDERR,json_encode(['event'=>'worker_pending','code'=>$e->getMessage()])."\n");if($e->getMessage()==='actual_host_window_yield')exit(0);if(in_array('--once',$argv,true))exit(1);$busy=false;}if(!$busy&&!in_array('--once',$argv,true))sleep($config['poll_seconds']??5);}while(!in_array('--once',$argv,true));}catch(Throwable $e){fwrite(STDERR,json_encode(['event'=>'worker_stopped','code'=>get_class($e)])."\n");exit(1);}
